(async function(){
"use strict";
function byId(id){return document.getElementById(id);}
var STORAGE_PREFIX="imposterGames.prototype.game.whoami.";
var STORAGE_PLAYERS=STORAGE_PREFIX+"players.v1",STORAGE_CATEGORIES=STORAGE_PREFIX+"categories.v1",STORAGE_DECK=STORAGE_PREFIX+"deck.v1";
var avatarPool=["😎","🕵️","🥷","🤠","👻","🤖","🦊","🐼","🐸","🦁","🐙","🦄"];
var appState=window.CIAppState||null;
var preferences=appState&&appState.getPreferences?appState.getPreferences():{sound:true,haptics:true,animations:true};
var soundEnabled=preferences.sound!==false,audioCtx=null,bank=[],categoryMeta=[];
var count=3,players=[],assignments=[],activeViewer=0,round=0,selectedCategories=["Alle"],savedPlayerNames=[],savedPlayerProfileIds=[],avatarSelections=[];
var sections=["setup","handoff","viewer","play","result"];
function storageGet(key,fallback){try{var raw=localStorage.getItem(key);return raw===null?fallback:JSON.parse(raw);}catch(e){return fallback;}}
function storageSet(key,value){try{localStorage.setItem(key,JSON.stringify(value));return true;}catch(e){return false;}}
function cleanName(v){return String(v==null?"":v).trim().slice(0,24);}
function randomUnit(){try{if(window.crypto&&window.crypto.getRandomValues){var a=new Uint32Array(1);window.crypto.getRandomValues(a);return a[0]/4294967296;}}catch(e){}return Math.random();}
function shuffle(list){var out=list.slice();for(var i=out.length-1;i>0;i--){var j=Math.floor(randomUnit()*(i+1)),t=out[i];out[i]=out[j];out[j]=t;}return out;}
function pulse(ms){if(preferences.haptics!==false&&navigator.vibrate)try{navigator.vibrate(ms||7);}catch(e){}}
function tone(freq,duration){if(!soundEnabled)return;try{var Ctx=window.AudioContext||window.webkitAudioContext;if(!Ctx)return;if(!audioCtx)audioCtx=new Ctx();if(audioCtx.state==="suspended")audioCtx.resume();var o=audioCtx.createOscillator(),g=audioCtx.createGain(),t=audioCtx.currentTime;o.type="sine";o.frequency.value=freq||520;g.gain.setValueAtTime(.0001,t);g.gain.exponentialRampToValueAtTime(.035,t+.008);g.gain.exponentialRampToValueAtTime(.0001,t+(duration||.06));o.connect(g);g.connect(audioCtx.destination);o.start(t);o.stop(t+(duration||.06)+.02);}catch(e){}}
function syncSound(){byId("soundOnIcon").classList.toggle("hidden",!soundEnabled);byId("soundOffIcon").classList.toggle("hidden",soundEnabled);byId("soundToggle").setAttribute("aria-pressed",soundEnabled?"true":"false");byId("soundToggle").setAttribute("aria-label",soundEnabled?"Sound ausschalten":"Sound einschalten");}
function show(id){sections.forEach(function(name){byId(name).classList.toggle("hidden",name!==id);});var active=id!=="setup";document.body.classList.toggle("game-active",active);byId("gameTopbar").classList.toggle("hidden",!active);if(active){byId("topRound").textContent="R"+Math.max(1,round);byId("topCategory").textContent=selectedCategories.indexOf("Alle")!==-1?"Alle":selectedCategories.length===1?selectedCategories[0]:selectedCategories[0]+" +"+(selectedCategories.length-1);}}
function renderLoadError(message){document.body.classList.remove("booting");document.body.removeAttribute("aria-busy");var app=byId("app");app.innerHTML="";var box=document.createElement("div");box.className="whoStageCard";box.style.minHeight="65dvh";var icon=document.createElement("div");icon.className="whoStageIcon";icon.textContent="!";var h=document.createElement("h2");h.textContent="Spiel konnte nicht geladen werden";var p=document.createElement("p");p.textContent=String(message||"Unbekannter Fehler");var a=document.createElement("a");a.href="../../";a.className="gameHubBack";a.textContent="Zurück zu den Spielen";a.style.marginTop="18px";box.append(icon,h,p,a);app.appendChild(box);}
try{var response=await fetch("../../data/who-am-i.json",{cache:"no-cache"});if(!response.ok)throw new Error("Begriffe konnten nicht geladen werden ("+response.status+").");var payload=await response.json();bank=Array.isArray(payload.items)?payload.items:[];categoryMeta=Array.isArray(payload.categories)?payload.categories:[];if(bank.length<24)throw new Error("Zu wenige Begriffe in der Datenbank.");}catch(error){renderLoadError(error&&error.message||error);return;}
function validProfileId(id,name){if(!appState||!id||!appState.getProfileById)return null;var p=appState.getProfileById(id);return p&&cleanName(p.name).toLocaleLowerCase("de-DE")===cleanName(name).toLocaleLowerCase("de-DE")?p.id:null;}
function loadSavedPlayers(){var stored=storageGet(STORAGE_PLAYERS,null);if(stored&&Array.isArray(stored.players)&&stored.players.length>=2){var list=stored.players.slice(0,12);count=Math.max(2,Math.min(12,list.length));savedPlayerNames=[];savedPlayerProfileIds=[];avatarSelections=[];list.forEach(function(item,i){item=item&&typeof item==="object"?item:{};var name=cleanName(item.name)||("Spieler "+(i+1));var avatar=avatarPool.indexOf(item.avatar)!==-1?item.avatar:avatarPool[i%avatarPool.length];savedPlayerNames.push(name);savedPlayerProfileIds.push(validProfileId(item.profileId,name));avatarSelections.push(avatar);});return true;}return false;}
function applyPreferredPlayers(){var group=appState&&appState.consumeLaunchGroup?appState.consumeLaunchGroup():null;var preferred=group&&group.length?group:(appState&&appState.getPreferredPlayers?appState.getPreferredPlayers(count):[]);if(group&&group.length)count=Math.max(2,Math.min(12,group.length));if(!preferred||!preferred.length)return;savedPlayerNames=[];savedPlayerProfileIds=[];avatarSelections=[];for(var i=0;i<count;i++){var p=preferred[i]||{id:null,name:"Spieler "+(i+1),avatar:avatarPool[i%avatarPool.length]};savedPlayerNames.push(cleanName(p.name)||("Spieler "+(i+1)));savedPlayerProfileIds.push(p.id||null);avatarSelections.push(avatarPool.indexOf(p.avatar)!==-1?p.avatar:avatarPool[i%avatarPool.length]);}}
function savePlayersFromInputs(){var nodes=byId("names").querySelectorAll("input"),list=[];for(var i=0;i<count;i++){var name=cleanName(nodes[i]&&nodes[i].value)||("Spieler "+(i+1));var profileId=validProfileId(savedPlayerProfileIds[i],name);savedPlayerProfileIds[i]=profileId;list.push({name:name,avatar:avatarSelections[i]||avatarPool[i%avatarPool.length],profileId:profileId});}savedPlayerNames=list.map(function(p){return p.name;});storageSet(STORAGE_PLAYERS,{players:list});}
function renderNames(){var box=byId("names");box.innerHTML="";while(savedPlayerNames.length<count)savedPlayerNames.push("Spieler "+(savedPlayerNames.length+1));while(savedPlayerProfileIds.length<count)savedPlayerProfileIds.push(null);while(avatarSelections.length<count)avatarSelections.push(avatarPool[avatarSelections.length%avatarPool.length]);savedPlayerNames=savedPlayerNames.slice(0,count);savedPlayerProfileIds=savedPlayerProfileIds.slice(0,count);avatarSelections=avatarSelections.slice(0,count);for(let i=0;i<count;i++){var row=document.createElement("div");row.className="playerRow";var av=document.createElement("button");av.type="button";av.className="playerAvatarButton";av.textContent=avatarSelections[i];av.setAttribute("aria-label","Avatar für Spieler "+(i+1)+" ändern");av.addEventListener("click",function(){var cur=avatarPool.indexOf(avatarSelections[i]);avatarSelections[i]=avatarPool[(cur+1)%avatarPool.length];av.textContent=avatarSelections[i];savePlayersFromInputs();tone(500,.04);});var inp=document.createElement("input");inp.type="text";inp.className="playerInput";inp.autocomplete="off";inp.maxLength=24;inp.value=savedPlayerNames[i];inp.placeholder="Spieler "+(i+1);inp.addEventListener("input",function(){savedPlayerProfileIds[i]=validProfileId(savedPlayerProfileIds[i],inp.value);});inp.addEventListener("blur",savePlayersFromInputs);row.append(av,inp);box.appendChild(row);}byId("minus").disabled=count<=2;byId("plus").disabled=count>=12;}
function validCategories(){return categoryMeta.map(function(x){return x.name;}).filter(Boolean);}
function loadCategories(){var saved=storageGet(STORAGE_CATEGORIES,["Alle"]);if(!Array.isArray(saved)){selectedCategories=["Alle"];return;}var valid=validCategories();if(saved.indexOf("Alle")!==-1){selectedCategories=["Alle"];return;}selectedCategories=saved.filter(function(x,i){return valid.indexOf(x)!==-1&&saved.indexOf(x)===i;});if(!selectedCategories.length)selectedCategories=["Alle"];}
function saveCategories(){storageSet(STORAGE_CATEGORIES,selectedCategories.slice());}
function selectedPool(){if(selectedCategories.indexOf("Alle")!==-1)return bank.slice();return bank.filter(function(item){return selectedCategories.indexOf(item.cat)!==-1;});}
function updatePoolCount(){byId("poolCount").textContent=selectedPool().length+" Begriffe verfügbar";}
function renderCategories(){var deck=byId("categoryDeck");deck.innerHTML="";var all=[{name:"Alle",emoji:"✨"}].concat(categoryMeta);all.forEach(function(meta){var name=meta.name||"",btn=document.createElement("button");btn.type="button";btn.className="categoryCard"+(selectedCategories.indexOf(name)!==-1?" selected":"");btn.setAttribute("aria-pressed",selectedCategories.indexOf(name)!==-1?"true":"false");var em=document.createElement("span");em.className="categoryEmoji";em.textContent=meta.emoji||"❔";var nm=document.createElement("span");nm.className="categoryName";nm.textContent=name;btn.append(em,nm);btn.addEventListener("click",function(){if(name==="Alle")selectedCategories=["Alle"];else{selectedCategories=selectedCategories.filter(function(x){return x!=="Alle";});var idx=selectedCategories.indexOf(name);if(idx===-1)selectedCategories.push(name);else selectedCategories.splice(idx,1);if(!selectedCategories.length)selectedCategories=["Alle"];}saveCategories();renderCategories();updatePoolCount();tone(540,.04);pulse(5);});deck.appendChild(btn);});}
function deckKey(){return selectedCategories.indexOf("Alle")!==-1?"Alle":selectedCategories.slice().sort().join("|");}
function drawTerms(amount){var pool=selectedPool();if(pool.length<amount)return null;var state=storageGet(STORAGE_DECK,{});if(!state||typeof state!=="object"||Array.isArray(state))state={};var key=deckKey(),used=Array.isArray(state[key])?state[key].map(String):[],available=pool.filter(function(item){return used.indexOf(String(item.id))===-1;});if(available.length<amount){used=[];available=pool.slice();}var picked=shuffle(available).slice(0,amount);state[key]=used.concat(picked.map(function(item){return String(item.id);}));storageSet(STORAGE_DECK,state);return picked;}
function collectPlayers(){var nodes=byId("names").querySelectorAll("input"),names=[],seen={};if(nodes.length<count)return {ok:false,message:"Spielerliste konnte nicht vollständig geladen werden."};for(var i=0;i<count;i++){var name=cleanName(nodes[i].value);if(!name)return {ok:false,message:"Bitte für jeden Spieler einen Namen eintragen."};var key=name.toLocaleLowerCase("de-DE");if(seen[key])return {ok:false,message:"Jeder Spieler braucht einen anderen Namen."};seen[key]=true;names.push(name);}players=[];for(var j=0;j<count;j++){var profileId=validProfileId(savedPlayerProfileIds[j],names[j]);if(!profileId&&appState&&appState.ensureProfileForPlayer&&!/^spieler\s+\d+$/i.test(names[j]))profileId=appState.ensureProfileForPlayer({name:names[j],avatar:avatarSelections[j]});savedPlayerProfileIds[j]=profileId||null;players.push({name:names[j],avatar:avatarSelections[j]||avatarPool[j%avatarPool.length],profileId:profileId||null});}savePlayersFromInputs();return {ok:true};}
function startRound(useExisting){if(!useExisting){var result=collectPlayers();if(!result.ok){byId("error").textContent=result.message;return;}}var terms=drawTerms(players.length);if(!terms){byId("error").textContent="Für diese Auswahl sind nicht genug unterschiedliche Begriffe vorhanden.";show("setup");return;}byId("error").textContent="";round++;assignments=players.map(function(player,i){return {name:player.name,avatar:player.avatar,profileId:player.profileId,term:terms[i].term,cat:terms[i].cat,id:terms[i].id};});activeViewer=0;showHandoff();tone(640,.07);pulse(8);}
function showHandoff(){var p=players[activeViewer];byId("handoffAvatar").textContent=p.avatar;byId("handoffName").textContent=p.name;show("handoff");}
function renderViewer(){var p=players[activeViewer];byId("viewerAvatar").textContent=p.avatar;byId("viewerName").textContent=p.name;byId("viewerProgress").textContent=(activeViewer+1)+"/"+players.length;var box=byId("termsList");box.innerHTML="";assignments.forEach(function(item,index){var row=document.createElement("div");row.className="whoTermRow"+(index===activeViewer?" self":"");var av=document.createElement("div");av.className="whoTermAvatar";av.textContent=item.avatar;var info=document.createElement("div");info.className="whoTermInfo";var name=document.createElement("span");name.textContent=item.name+(index===activeViewer?" · DU":"");var term=document.createElement("strong");term.textContent=index===activeViewer?"???":item.term;info.append(name,term);row.append(av,info);box.appendChild(row);});byId("viewerDone").textContent=activeViewer===players.length-1?"Gesehen · Fertig":"Gesehen · Weitergeben";show("viewer");tone(560,.045);}
function finishViewer(){if(activeViewer<players.length-1){activeViewer++;showHandoff();pulse(5);return;}show("play");tone(690,.07);pulse(9);}
function renderResult(){var box=byId("resultList");box.innerHTML="";assignments.forEach(function(item){var row=document.createElement("div");row.className="whoResultRow";var av=document.createElement("div");av.className="whoResultAvatar";av.textContent=item.avatar;var info=document.createElement("div");info.className="whoResultInfo";var meta=document.createElement("span");meta.textContent=item.name+" · "+item.cat;var term=document.createElement("strong");term.textContent=item.term;info.append(meta,term);row.append(av,info);box.appendChild(row);});show("result");tone(760,.09);pulse(12);}
function toggleSound(){soundEnabled=!soundEnabled;if(appState&&appState.setPreference)appState.setPreference("sound",soundEnabled);preferences.sound=soundEnabled;syncSound();if(soundEnabled)tone(620,.05);}
var hadSaved=loadSavedPlayers();
if(!hadSaved)applyPreferredPlayers();else{var launchGroup=appState&&appState.consumeLaunchGroup?appState.consumeLaunchGroup():null;if(launchGroup&&launchGroup.length){count=Math.max(2,Math.min(12,launchGroup.length));savedPlayerNames=[];savedPlayerProfileIds=[];avatarSelections=[];for(var gi=0;gi<count;gi++){var gp=launchGroup[gi];savedPlayerNames.push(gp.name);savedPlayerProfileIds.push(gp.id);avatarSelections.push(avatarPool.indexOf(gp.avatar)!==-1?gp.avatar:avatarPool[gi%avatarPool.length]);}}}
loadCategories();renderCategories();renderNames();updatePoolCount();syncSound();if(preferences.animations===false)document.body.classList.add("experimentReduceMotion");
byId("minus").addEventListener("click",function(){if(count>2){savePlayersFromInputs();count--;renderNames();tone(430,.04);}});
byId("plus").addEventListener("click",function(){if(count<12){savePlayersFromInputs();count++;renderNames();tone(520,.04);}});
byId("start").addEventListener("click",function(){startRound(false);});
byId("showTerms").addEventListener("click",renderViewer);
byId("viewerDone").addEventListener("click",finishViewer);
byId("revealAll").addEventListener("click",renderResult);
byId("newRound").addEventListener("click",function(){startRound(true);});
byId("backSetup").addEventListener("click",function(){show("setup");window.scrollTo(0,0);});
byId("freshRound").addEventListener("click",function(){if(players.length>=2)startRound(true);});
byId("leaveGame").addEventListener("click",function(){window.location.href="../../";});
byId("soundToggle").addEventListener("click",toggleSound);
show("setup");document.body.classList.remove("booting");document.body.removeAttribute("aria-busy");
})();